			["name"]="Refiner's Bargain",
			["icon"]="Art/2DArt/SkillIcons/passives/AtlasTrees/KalguurKeystone.png",
			["isKeystone"]=true,
			["stats"]={"Equipment Items with Rarity dropped by Possessed Monsters in your Maps have 5% chance to be converted to Thaumaturgic Dust","Sulphite found in your Maps is granted as a random Ore instead at 10% of the value","Lifeforce found in your Maps is granted as a random Crop instead at 250% of the value"},
