		["58043"]={
			["skill"]=58043,
			["name"]="Endless Tide",
			["icon"]="Art/2DArt/SkillIcons/passives/AtlasTrees/EndlessTide.png",
			["isKeystone"]=true,
			["stats"]={"Beyond Portals in your Maps cannot spawn Unique Bosses\nBeyond Portals in your Maps have 50% less Merging Radius"},
			["reminderText"]={"(Beyond Portals and Demons stop spawning after a Unique Beyond Boss is spawned)","(Merging Radius is the distance at which Beyond Portals can merge with one another to spawn Beyond Demons)"},
			["flavourText"]={"You fight on, muscles burning, limbs leaden,","hoping for that singular moment of victory that","might finally bring relief... but it never comes."},
