			["isKeystone"]=true,
			["stats"]={"Tormented Spirits in your Maps can Possess Players for 20 seconds\nTormented Spirits in your Maps cannot Possess Monsters"},
			["reminderText"]={"(Players can Touch up to 40 nearby normal or magic Monsters for each Tormented Spirit Possessing them)"},
